<?php
namespace App\Tests\Service;
use App\Entity\Groupe;use App\Entity\GroupeMember;use App\Entity\User;use App\Repository\GroupeJoinRequestRepository;use App\Repository\GroupeMemberRepository;use App\Service\GroupeMembershipService;use Doctrine\ORM\EntityManagerInterface;use PHPUnit\Framework\TestCase;
final class GroupeMembershipServiceTest extends TestCase {private function user():User{return (new User())->setUsername('u'.uniqid())->setEmail(uniqid().'@test.local')->setPasswordHash('x')->setStatus('ACTIVE');}public function testPublicFactionJoinsImmediately():void{$em=$this->createMock(EntityManagerInterface::class);$members=$this->createMock(GroupeMemberRepository::class);$requests=$this->createMock(GroupeJoinRequestRepository::class);$creator=$this->user();$group=new Groupe('Quartz Club','quartz-club',$creator);$user=$this->user();$members->method('findActive')->willReturn(null);$em->expects($this->once())->method('persist')->with($this->isInstanceOf(GroupeMember::class));$em->expects($this->once())->method('flush');$result=(new GroupeMembershipService($em,$members,$requests))->join($group,$user);self::assertInstanceOf(GroupeMember::class,$result);self::assertSame(GroupeMember::MEMBER,$result->getRole());}public function testOwnerCannotLeave():void{$em=$this->createMock(EntityManagerInterface::class);$members=$this->createMock(GroupeMemberRepository::class);$creator=$this->user();$group=new Groupe('Quartz Club','quartz-club',$creator);$members->method('findActive')->willReturn(new GroupeMember($group,$creator,GroupeMember::OWNER));$this->expectException(\LogicException::class);(new GroupeMembershipService($em,$members,$this->createMock(GroupeJoinRequestRepository::class)))->leave($group,$creator);}}
